28:         match component {
29:             Component::Prefix(_) | Component::RootDir => {
30:                 return Err(ModelError::AbsolutePath {
31:                     path: p.to_path_buf(),
32:                 });
33:             }
34:             Component::CurDir => {}
35:             Component::ParentDir => {
36:                 if let Some(Component::Normal(_)) = components.last() {
37:                     components.pop();
38:                 } else {
39:                     return Err(ModelError::PathTraversal {
40:                         path: p.to_path_buf(),
41:                     });
42:                 }
43:             }
